```java
// AuthController.java
@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public ResponseEntity<TokenResponse> login(@RequestBody @Valid LoginRequest req) {
        return ResponseEntity.ok(authService.login(req));
    }

    @PostMapping("/refresh")
    public ResponseEntity<TokenResponse> refresh(@RequestBody RefreshRequest req) {
        return ResponseEntity.ok(authService.refresh(req.refreshToken()));
    }

    @PostMapping("/logout")
    public ResponseEntity<Void> logout(@RequestHeader("Authorization") String bearer) {
        authService.logout(bearer.substring(7));
        return ResponseEntity.noContent().build();
    }
}

// AuthService.java
@Service
public class AuthService {

    private final UserRepository users;
    private final PasswordEncoder encoder;
    private final JwtService jwt;
    private final TokenStore tokenStore;

    public AuthService(UserRepository users, PasswordEncoder encoder,
                       JwtService jwt, TokenStore tokenStore) {
        this.users = users;
        this.encoder = encoder;
        this.jwt = jwt;
        this.tokenStore = tokenStore;
    }

    public TokenResponse login(LoginRequest req) {
        User user = users.findByUsername(req.username())
                .orElseThrow(() -> new BadCredentialsException("invalid credentials"));

        if (!encoder.matches(req.password(), user.getPasswordHash())) {
            throw new BadCredentialsException("invalid credentials");
        }

        String access = jwt.issueAccess(user.getId(), user.getRoles());
        String refresh = jwt.issueRefresh(user.getId());
        tokenStore.save(user.getId(), refresh);
        return new TokenResponse(access, refresh);
    }

    public TokenResponse refresh(String refreshToken) {
        Long userId = jwt.parseRefresh(refreshToken);
        if (!tokenStore.isValid(userId, refreshToken)) {
            throw new BadCredentialsException("refresh revoked");
        }
        User user = users.findById(userId).orElseThrow();
        String access = jwt.issueAccess(user.getId(), user.getRoles());
        return new TokenResponse(access, refreshToken);
    }

    public void logout(String accessToken) {
        Long userId = jwt.parseAccess(accessToken);
        tokenStore.revokeAll(userId);
    }
}
```

