    }
}

@Service
public class AuthService {

    private final UserRepository users;
    private final PasswordEncoder encoder;
    private final JwtIssuer jwt;

    public AuthService(UserRepository users, PasswordEncoder encoder, JwtIssuer jwt) {
        this.users = users;
        this.encoder = encoder;
        this.jwt = jwt;
    }

    public TokenPair login(LoginRequest req) {
        var user = users.findByEmail(req.email())
            .orElseThrow(() -> new BadCredentialsException("invalid credentials"));

        if (!encoder.matches(req.password(), user.getPasswordHash())) {
            throw new BadCredentialsException("invalid credentials");
        }

        return jwt.issue(user.getId(), user.getRoles());
    }

    public TokenPair refresh(String refreshToken) {
        var claims = jwt.verify(refreshToken);
        return jwt.issue(claims.subjectId(), claims.roles());
    }
}
```

Замечания для плана:
- пароли — BCrypt/Argon2, не самописный хеш;
- токены — короткий access + refresh с ротацией и отзывом;
- одинаковый ответ на неверный email и неверный пароль (не светить существование пользователя);
- секреты ключей — из окружения, не в коде.

